def main():
    out = {
        'wave': 'round-51-w1',
        'reportDir': '.ufo/waves/round-51/w1',
        'template': TEMPLATE,
        'context': CONTEXT,
        'items': [{'name': P + n, 'role': r, 'axes': a, 'milestone': ms, 'item': fill(t)} for n, r, a, ms, t in ITEMS],
    }
    for it in out['items']:
        if '@' in it['item'].replace('@m_', '') and any(tok in it['item'] for tok in ('@LANE@', '@E@', '@W1@', '@SCR@', '@BASE@', '@FREEZE@', '@P@', '@FLEET@', '@KAGI@')):
            raise SystemExit('unfilled placeholder in ' + it['name'])
    names = [it['name'] for it in out['items']]
    assert len(names) == len(set(names)), 'duplicate names'
    here = os.path.dirname(os.path.abspath(__file__))
    path = os.path.join(here, 'spec-w1.json')
    with open(path, 'w', encoding='utf-8') as fh:
        json.dump(out, fh, indent=2, ensure_ascii=False)
    roles = {}
    for it in out['items']:
        roles[it['role']] = roles.get(it['role'], 0) + 1
    print('wrote %s with %d items %s' % (path, len(out['items']), json.dumps(roles, sort_keys=True)))


if __name__ == '__main__':
    main()
